/* Cash on delivery (Settings › Checkout, "Cash on delivery"): a physical order a buyer pays in cash when it is delivered or picked up. commerce_checkouts.provider takes 'cod' beside 'stripe' and 'free' (the column's check is found by what it checks, replaced, and allows every value already in the table too, so no row can fail it), and cod_collected_at is when the seller marked the cash received (null: still to collect). The switch itself is a key of the store's checkout settings, no column. No fee is taken and nothing goes on the payout ledger: the money never passes through Storelib. Safe to run again. */
DO $do$ DECLARE c record; allowed text; BEGIN IF to_regclass('public.commerce_checkouts') IS NULL THEN RAISE NOTICE 'cash on delivery: commerce_checkouts is not there yet, run the physical commerce parts first.'; RETURN; END IF; FOR c IN SELECT conname FROM pg_constraint WHERE conrelid = 'public.commerce_checkouts'::regclass AND contype = 'c' AND pg_get_constraintdef(oid) ~ '\mprovider\M' LOOP EXECUTE format('ALTER TABLE public.commerce_checkouts DROP CONSTRAINT %I', c.conname); END LOOP; SELECT string_agg(quote_literal(v), ', ' ORDER BY v) INTO allowed FROM (SELECT unnest(ARRAY['stripe', 'free', 'cod']) AS v UNION SELECT DISTINCT provider FROM public.commerce_checkouts WHERE provider IS NOT NULL) s; EXECUTE format('ALTER TABLE public.commerce_checkouts ADD CONSTRAINT commerce_checkouts_provider_check CHECK (provider IN (%s))', allowed); ALTER TABLE public.commerce_checkouts ADD COLUMN IF NOT EXISTS cod_collected_at timestamptz; END $do$;
notify pgrst, 'reload schema';
